#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    long long n, a, b;
    cin >> n >> a >> b;

    long long low = 1, high = max(a, b), answer = 0;

    while (low <= high) {
        long long mid = low + (high - low) / 2;

        if (a / mid + b / mid >= n) {
            answer = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    cout << answer;
    return 0;
}

